#!/bin/sh
# Writes Asqu's Homebrew formula for one release, using that release's fingerprints.
#
#   sh scripts/brew-formula.sh v0.1.8 <folder with asqu-*.tar.gz.sha256 files>  > Formula/asqu.rb
#
# The download addresses are per-version (dl.asqu.dev/v0.1.8/..., on Cloudflare R2), so they
# never change.
set -eu
tag="$1"
dir="$2"
version="${tag#v}"
base="https://dl.asqu.dev/${tag}"
sha() { cut -d ' ' -f 1 <"${dir}/asqu-$1.tar.gz.sha256"; }

cat <<RUBY
# typed: strict
# frozen_string_literal: true

# Generated by scripts/brew-formula.sh in iDevEngineer/asqu for ${tag}. Don't edit by hand.
class Asqu < Formula
  desc "Version control that nobody has to manage: save, see and undo in plain words"
  homepage "https://asqu.dev"
  license "FSL-1.1-ALv2"
  version "${version}"

  on_macos do
    on_arm do
      url "${base}/asqu-aarch64-apple-darwin.tar.gz"
      sha256 "$(sha aarch64-apple-darwin)"
    end
    on_intel do
      url "${base}/asqu-x86_64-apple-darwin.tar.gz"
      sha256 "$(sha x86_64-apple-darwin)"
    end
  end

  on_linux do
    on_intel do
      url "${base}/asqu-x86_64-unknown-linux-musl.tar.gz"
      sha256 "$(sha x86_64-unknown-linux-musl)"
    end
  end

  def install
    bin.install "asqu"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/asqu --version")
  end
end
RUBY
